    for bi,b in enumerate(boxes):
        # mode: 'reverse' assigns colors in reversed order, 'nearest' picks nearest dot
        if mode=='reverse':
            pick=dotcolors[-1-bi]
        else:
            best=None
            for i,j,c in D:
                if c in boxcols: continue
                d=min(abs(i-y)+abs(j-x) for y in range(b['r0']+1,b['r1']) for x in range(b['c0']+1,b['c1']))
                if best is None or d<best[0]: best=(d,c)
            pick=best[1]
        for y in range(b['r0']+1,b['r1']):
            for x in range(b['c0']+1,b['c1']):
                if (y+x)%2==0: out[y][x]=pick
    return out,D,boxes

