from collections import Counter
def components(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                c=g[i][j]; stack=[(i,j)]; seen[i][j]=True; cells=[]
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                            seen[ny][nx]=True; stack.append((ny,nx))
                comps.append((c,cells))
    return comps
# check on demos: does f = fill interior match outputs?
def fill_interior(g):
    out=[r[:] for r in g]
    H,W=len(g),len(g[0])
    comps=components(g)
    for c,cells in comps:
        ys=[y for y,x in cells]; xs=[x for y,x in cells]
        # hollow: interior = bbox minus outline cells
        inner=[(y,x) for y in range(min(ys),max(ys)+1) for x in range(min(xs),max(xs)+1)
                if g[y][x]==0 or not (y,x) in set(cells)]
        for y,x in inner:
            if 0<y<H-1 and 0<x<W-1:
                out[y][x]=c
    return out
